/* Chat screen chrome. Locks inside <AppShell> (which sets viewport height for
 * `:has(.chat-shell)`); only the inner regions scroll. Columns:
 *   default            [history | thread]
 *   data-with-panel    [history | thread | panel]
 *   collapsed          history column shrinks to its icon rail (auto). */
.chat-shell {
  height: 100%;
  min-height: 0;
  display: flex;
  flex-direction: column;
  color: var(--foreground);
}
/* The leading slot, mobile only: the chat has no PageHeader to hold it. */
.chat-shell-bar { display: none; }
.chat-shell-content {
  flex: 1;
  min-height: 0;
  display: flex;
  padding: var(--space-4);
}
.chat-shell-body {
  flex: 1;
  min-height: 0;
  display: grid;
  grid-template-columns: var(--chat-sidebar-width) 1fr;
  background: var(--card);
  /* A white surface that is not `.card`, so it owes its own answer — see
   * --surface-contrast in semantic.css. Without these a quiet control on it
   * takes the PAGE's answer, which is white, and stands white on white. */
  border-radius: var(--card-radius);
  overflow: hidden;
}
.chat-shell-body[data-with-panel] {
  grid-template-columns: var(--chat-sidebar-width) 1fr var(--chat-panel-width);
}
.chat-shell[data-chat-collapsed] .chat-shell-body {
  grid-template-columns: auto 1fr;
}
.chat-shell[data-chat-collapsed] .chat-shell-body[data-with-panel] {
  grid-template-columns: auto 1fr var(--chat-panel-width);
}
/* No history column (no chats yet): thread spans the surface. */
.chat-shell-body[data-no-sidebar] { grid-template-columns: 1fr; }
.chat-shell-body[data-no-sidebar][data-with-panel] { grid-template-columns: 1fr var(--chat-panel-width); }

/* <72rem: drop the panel column (the page hides the panel element itself). */
@media (max-width: 72rem) {
  .chat-shell-body[data-with-panel],
  .chat-shell[data-chat-collapsed] .chat-shell-body[data-with-panel] {
    grid-template-columns: var(--chat-sidebar-width) 1fr;
  }
}
/* <48rem: single column (sidebar becomes the app drawer). */
@media (max-width: 48rem) {
  .chat-shell-bar {
    display: flex;
    padding: var(--space-3) var(--space-4) 0;
  }
  .chat-shell-body,
  .chat-shell-body[data-with-panel] { grid-template-columns: 1fr; }
}

/* THE THREAD COLUMN, WHICH THE SHELL OWES AND DID NOT SHIP.
 * The golden example put `<h1>` and the composer inside `.chat-shell-thread`
 * and the class existed nowhere: not here, not in styles/, not in any app.
 * With `* { margin: 0 }` from the reset that is a block box with no padding
 * and no gap, so the greeting sat directly on the composer and its descenders
 * crossed the 2px border (owner, read off the gallery, 2026-08-29). The
 * registry publishes that snippet to agents as the shape to copy, so the class
 * had to become real rather than leave the example. It carries the three
 * things the column has to answer: it is the region that scrolls (the shell
 * itself never does), the conversation keeps the 44rem measure the system
 * already named, and the turns are separated. */
.chat-shell-thread {
  min-inline-size: 0;
  min-block-size: 0;
  overflow-y: auto;
  display: flex;
  flex-direction: column;
  gap: var(--space-6);
  padding: var(--space-6);
}
/* A conversation full-bleed on a 1280px card puts the two turns against
 * opposite edges and stops reading as an exchange (the same reason
 * ChatMessage's own example spans six columns of twelve). The measure lives on
 * the children so the SCROLLBAR stays on the column edge, where a reader looks
 * for it, rather than on a centred box inside it. */
.chat-shell-thread > * {
  inline-size: 100%;
  max-inline-size: var(--chat-message-max-width);
  margin-inline: auto;
}

import './ChatShell.css'
import { type ReactNode } from 'react'
import { NavDrawerButton } from '../NavDrawerButton'

type Props = {
  /** Icon-rail state of the chat-history column (drives the grid + ChatHistory). */
  collapsed?: boolean
  /** Show the optional right-hand panel column (e.g. a form). */
  panel?: boolean
  /** Drop the history column entirely (e.g. when there are no chats). */
  noSidebar?: boolean
  children: ReactNode
}

/* Shared chrome for chat screens: full-height column → padded region → one
 * rounded card surface that lays its children out in a grid
 * [history | thread | optional panel]. Lives inside <AppShell>. */
export function ChatShell({ collapsed, panel, noSidebar, children }: Props) {
  return (
    <div className="chat-shell" data-chat-collapsed={collapsed || undefined}>
      {/* The chat is the one top-level destination in this system with no
          <PageHeader>, so it carries the leading slot itself. That single
          exception is why the trigger used to float over every OTHER screen:
          one screen's missing bar was solved by putting a fixed button on all of
          them, where it collided with the header. It renders nothing above the
          drawer breakpoint. */}
      <div className="chat-shell-bar">
        <NavDrawerButton />
      </div>
      <div className="chat-shell-content">
        <div className="chat-shell-body" data-raised="card" data-with-panel={panel || undefined} data-no-sidebar={noSidebar || undefined}>
          {children}
        </div>
      </div>
    </div>
  )
}
